	nr := NewRule(r)
	assert.Equal(t, nr.Rank, r.Rank)
	assert.Equal(t, nr.Id, r.Id)
	assert.Equal(t, nr.FlagKey, r.FlagKey)
	assert.Equal(t, nr.SegmentKey, r.SegmentKey)

	for _, d := range r.Distributions {
		testDistributionHelper(t, d)
	}
}

